$ctx=$db->query("SELECT s.id subject_id,st.id student_id,c.reg_id,c.id class_id,f.id faculty_id,f.username faculty_username,uf.id faculty_user_id,dep.username hod_username,uh.id hod_user_id FROM subjects s JOIN classes c ON c.id=s.class_id JOIN specialization sp ON sp.id=c.spec_id JOIN departments dep ON dep.id=sp.dept_id JOIN users uh ON uh.username=dep.username AND uh.role='hod' JOIN faculty_sub fs ON fs.sub_id=s.id JOIN faculties f ON f.id=fs.faculty_id JOIN users uf ON uf.username=f.username AND uf.role='faculty' JOIN student_sub ss ON ss.sub_id=s.id JOIN students st ON st.id=ss.stu_id WHERE EXISTS(SELECT 1 FROM academic_settings a WHERE a.reg_id=c.reg_id AND a.setting_key='lab_cia_day_to_day_marks') AND EXISTS(SELECT 1 FROM academic_settings a WHERE a.reg_id=c.reg_id AND a.setting_key='lab_cia_internal_test_marks') AND EXISTS(SELECT 1 FROM diary d WHERE d.sub_id=s.id) LIMIT 1")->fetch_assoc();
