$lab=new Services\LabAssessmentService();$assessment=200; // Isolated fixture outside existing assessments.
$grid=['sub_id'=>$ctx['subject_id'],'assessment_number'=>$assessment,'submit_action'=>'save','student_id'=>[$ctx['student_id']],'day_to_day_marks'=>[0],'internal_test_marks'=>[0]];
$lab->save($grid);check(true,'lab draft save');$grid['submit_action']='submit';
$criteria=$db->query('SELECT id FROM lab_subject_rubrics WHERE subject_id='.(int)$ctx['subject_id'])->fetch_all(MYSQLI_ASSOC);
if(!$criteria){$criteria=$db->query('SELECT c.id FROM lab_rubric_criteria c JOIN lab_rubric_templates t ON t.id=c.template_id WHERE t.is_default=1')->fetch_all(MYSQLI_ASSOC);}
$breakdown=array_fill_keys(array_column($criteria,'id'),0);$grid['rubric_breakdown']=[$ctx['student_id']=>$breakdown];
$invalid=$grid;$invalid['rubric_breakdown'][$ctx['student_id']][999999]=0;rejects(fn()=>$lab->save($invalid),'unknown rubric rejected');
$db->query("CREATE TRIGGER cea_lab_failure BEFORE INSERT ON lab_rubric_evaluations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test rubric rollback'");
$failed=false;try{$lab->save($grid);}catch(Throwable $e){$failed=true;}$db->query('DROP TRIGGER cea_lab_failure');check($failed,'simulated rubric failure');
check((int)$db->query('SELECT COUNT(*) FROM uglab_internal_assessment_marks WHERE subject_id='.(int)$ctx['subject_id'].' AND assessment_number='.$assessment)->fetch_row()[0]===0,'lab submission rolled back');
$lab->save($grid);check(true,'valid rubric transaction');rejects(fn()=>$lab->save($grid),'duplicate lab submission rejected');
$plan=new Services\LessonPlanService();
