$r=$plan->addOrUpdateLecturePlan(['sub_id'=>(int)$ctx['subject_id'],'unit_number'=>1,'lecture_number'=>9999,'planned_topic'=>'Isolated test','co_id'=>(int)$co[0],'planned_hours'=>1]);check($r['status']===1,'lesson plan creation');
$lp=(int)$db->query('SELECT id FROM lesson_plans WHERE sub_id='.(int)$ctx['subject_id'].' AND lecture_number=9999')->fetch_row()[0];
$diary=(int)$db->query('SELECT id FROM diary WHERE sub_id='.(int)$ctx['subject_id'].' LIMIT 1')->fetch_row()[0];check($plan->saveDiaryLessonPlanMappings((int)$ctx['subject_id'],[$diary=>$lp])['status']===1,'map own diary');
$r=$plan->saveCourseCompletionAudit(['sub_id'=>(int)$ctx['subject_id'],'faculty_id'=>999999,'total_planned_lectures'=>999999,'syllabus_completion_pct'=>999,'deviations_reason'=>'ISOLATED TEST','is_final_submission'=>1]);check($r['status']===1,'submit from computed evidence');
$audit=$plan->getCourseCompletionAudit((int)$ctx['subject_id']);check((int)$audit['faculty_id']===(int)$ctx['faculty_id']&&(int)$audit['total_planned_lectures']<999999&&(float)$audit['syllabus_completion_pct']<=100,'posted actor and totals ignored');
check($plan->saveCourseCompletionAudit(['sub_id'=>(int)$ctx['subject_id'],'faculty_id'=>$ctx['faculty_id']])['status']===0,'submitted course locked');
$_SESSION=$hod;$review=new Services\AcademicReviewService();$review->decide('COURSE',(int)$audit['id'],'APPROVED','Verified isolated evidence');
check(College\ReportValue::certified($plan->getCourseCompletionAudit((int)$ctx['subject_id'])),'certificate requires persisted HOD approval');
rejects(fn()=>$review->decide('COURSE',(int)$audit['id'],'APPROVED','Repeat'),'course review once');
$db->query("INSERT INTO course_cqi_actions(sub_id,co_id,academic_year,target_benchmark,attained_percentage,attainment_gap,action_proposed,faculty_id) VALUES (".(int)$ctx['subject_id'].",".(int)$co[0].",'ISOLATED',60,40,20,'Isolated workflow fixture',".(int)$ctx['faculty_id'].")");$cqi=$db->insert_id;
$review->decide('CQI',$cqi,'APPROVED','Approved isolated action',date('Y-m-d'));
rejects(fn()=>$review->decide('CQI',$cqi,'CLOSED','Premature','', 'Measure'),'cannot close unexecuted CQI');
$_SESSION=$faculty;$review->decide('CQI',$cqi,'COMPLETED','Remedial class attendance and assessment evidence recorded.');
$_SESSION=$hod;$review->decide('CQI',$cqi,'CLOSED','Review complete',null,'Follow-up assessment reviewed.');
check((bool)$db->query('SELECT closed_at FROM course_cqi_actions WHERE id='.$cqi)->fetch_row()[0],'CQI full lifecycle');
$_SESSION=[];
$tc=$db->query('SELECT c.*,ct.id hour_id FROM classes c JOIN class_timings ct ON ct.timing_id=c.timing_id WHERE c.end_date>=CURRENT_DATE AND ct.start_time<ct.end_time LIMIT 1')->fetch_assoc();
if($tc){$writer=new College\TimetableWriter($db,[]);$db->query("DELETE FROM class_timetables WHERE class_id=".(int)$tc['id']." AND weekday='Sunday'");$writer->add((int)$tc['id'],'Sunday',(int)$tc['hour_id'],null,'TEST','TEST','Isolated activity');rejects(fn()=>$writer->add((int)$tc['id'],'Sunday',(int)$tc['hour_id'],null,'TEST','TEST','Duplicate'),'class overlap rejected');}
require_once dirname(__DIR__).'/services/StudentProfileService.php';
