$_SESSION=['userid'=>(int)$admin['id'],'user'=>$admin['username'],'role'=>'admin'];
$profile=new Services\StudentProfileService();$beforeEmail=$db->query("SELECT email FROM users WHERE username='".$db->real_escape_string($st)."'")->fetch_row()[0];
