$stored=$db->query('SELECT * FROM report_snapshots WHERE id='.(int)$snap['id'])->fetch_assoc();
check(hash('sha256',$stored['scope_json']."\n".$stored['metrics_json'])===$stored['metrics_hash'],'report snapshot hash reproduces its evidence');
check(json_decode($stored['metrics_json'],true)===$metrics,'report snapshot preserves metrics');
