check($profile->updateCertificateStatus($rid,'ISSUED',(int)$admin['id'],'Issued to applicant'),'certificate issue state');
check($approval===$db->query('SELECT approved_by,approved_at FROM student_certificate_requests WHERE id='.$rid)->fetch_assoc(),'certificate issuance preserves original approver');
