$co=['co_label'=>'CO1','cia_pct'=>50,'see_pct'=>60,'cia_level'=>1,'see_level'=>2,'direct_attainment'=>1.7,'overall_attainment'=>1.7,'indirect_pct'=>null];
$action=['action_proposed'=>'Proposed isolated intervention','hod_review_status'=>'PENDING'];
$html=(new ReflectionMethod($obe,'renderSARFormC3Html'))->invoke($obe,$meta,[$co],[],[1=>$action],null,.3,.7,.8,.2,60,2);
check(str_contains($html,'INCOMPLETE EVIDENCE')&&str_contains($html,'Execution evidence not recorded.'),'SAR separates missing evidence and proposed action');
check(!str_contains($html,'conducted before SEE')&&!str_contains($html,'Official NBA')&&!str_contains($html,'Concept complexity in core derivations'),'SAR never invents remedial execution or certification');
$action['completed_at']=date('Y-m-d H:i:s');$action['execution_evidence']='Recorded isolated execution';
$html=(new ReflectionMethod($obe,'renderSARFormC3Html'))->invoke($obe,$meta,[$co],[],[1=>$action],null,.3,.7,.8,.2,60,2);
check(str_contains($html,'Recorded execution evidence: Recorded isolated execution'),'SAR uses persisted execution evidence');
$generator=new OBEAnalysisPDFService();$_SESSION=$faculty;
$html=(new ReflectionMethod($generator,'renderSEEResultAnalysisHtml'))->invoke($generator,(int)$ctx['subject_id']);
check(!str_contains($html,'CO1, CO2, CO4, and CO5 achieved')&&!str_contains($html,'robust student mastery'),'SEE report has no hard-coded course findings');
$html=(new ReflectionMethod($generator,'renderCombinedDirectAttainmentHtml'))->invoke($generator,(int)$ctx['subject_id'],.3,.7);
check(!str_contains($html,'solid compliance with NBA'),'direct report never certifies compliance from an average');
rejects(fn()=>(new ReflectionMethod($generator,'requiredPolicySetting'))->invoke($generator,'MISSING_POLICY_TEST',(string)$ctx['reg_id']),'dossier refuses missing policy instead of borrowing defaults');
foreach(['attainment_direct_cia_weight'=>.3,'attainment_direct_see_weight'=>.7,'overall_direct_weight'=>.8,'overall_indirect_weight'=>.2,'co_target_percentage'=>60,'target_attainment_level'=>2] as $key=>$value){
 $str=(string)$value;$regId=(int)$ctx['reg_id'];$stmt=$db->prepare("INSERT INTO academic_settings(reg_id,regulation_code,category,setting_key,setting_value,data_type) SELECT id,regulation,'ATTAINMENT',?,?,'FLOAT' FROM regulations WHERE id=? ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$stmt->bind_param('ssi',$key,$str,$regId);$stmt->execute();
}
Services\SettingsService::getInstance()->clearCache();
